    [1463] = { en = "Absorbs $s1 physical damage, draining mana instead.  Drains $e mana per damage absorbed.  Lasts $d.", description = "Assorbe $s1 danni fisici, consumando mana al loro posto.  Consuma $e mana per ogni danno assorbito.  Dura $d." },
