    [6572] = { en = "Instantly counterattack an enemy for $s1 damage and a high amount of threat.   Revenge must follow a block, dodge or parry.", description = "Contrattacca istantaneamente un nemico, infliggendo $s1 danni e generando molta minaccia.   Revenge può essere usata solo dopo un blocco, una schivata o una parata." },
    [7371] = { en = "Charges an enemy, immobilizes it for $7922d, and adds $s2 melee attack power to the boar's next attack.", description = "Carica un nemico e lo immobilizza per $7922d; il prossimo attacco del cinghiale ottiene inoltre $s2 potenza d'attacco in mischia." },
    [7812] = { en = "Sacrifices the Voidwalker, giving its owner a shield that will absorb $s1 damage for $d.  While the shield holds, spellcasting will not be interrupted by damage.", description = "Sacrifica il Voidwalker, conferendo al padrone uno scudo che assorbe $s1 danni per $d.  Finché lo scudo regge, i danni non interrompono il lancio degli incantesimi." },
    [8091] = { en = "Increases the target's Armor by $s1 for $d.", description = "Aumenta l'armatura del bersaglio di $s1 per $d." },
    [8990] = { en = "Causes $s1 Holy damage to any creature that strikes a nearby party member. Players may only have one aura on them per paladin at any one time. The aura lasts until cancelled.", description = "Infligge $s1 danni sacri a ogni creatura che colpisce un membro del gruppo vicino. Ogni paladino può avere attiva su un giocatore una sola aura alla volta. L'aura dura finché non viene annullata." },
    [11319] = { en = "Lets you walk on water for $d.", description = "Ti permette di camminare sull'acqua per $d." },
    [13323] = { en = "Transforms an enemy into a sheep, forcing it to wander around for up to $d. While wandering, the sheep cannot attack or cast spells, but regenerates very quickly. Any damage will transform the target back into its normal form. Only one target can be polymorphed at a time. Only works on beasts, dragons, giants, humanoids, and critters.", description = "Trasforma un nemico in una pecora, costringendolo a vagare per un massimo di $d. Mentre vaga, la pecora non può attaccare né lanciare incantesimi, ma si rigenera molto rapidamente. Qualsiasi danno riporta il bersaglio alla sua forma normale. Può essere trasformato un solo bersaglio alla volta. Funziona solo su bestie, draghi, giganti, umanoidi e piccole creature." },
    [13705] = { en = "Improves your chance to hit by $s1%.", description = "Aumenta del $s1% la tua probabilità di colpire." },
    [14318] = { en = "The hunter takes on the aspects of a hawk, increasing Ranged Attack Power by $s1.  Only one Aspect can be active at a time.", description = "Il cacciatore assume l'Aspetto del Falco, aumentando di $s1 la potenza d'attacco a distanza.  Può essere attivo un solo Aspetto alla volta." },
    [15407] = { en = "Assault the target's mind with Shadow energy, causing $o1 Shadow damage over $d  and slowing their movement speed by $m2%.", description = "Assalta la mente del bersaglio con energia d'ombra, infliggendo $o1 danni da ombra in $d  e riducendone la velocità di movimento del $m2%." },
    [17767] = { en = "The Voidwalker consumes nearby shadows to bolster its form, recovering $o1 health over $d.  Cannot be used while in combat.", description = "Il Voidwalker assorbe le ombre vicine per rafforzare la propria forma, recuperando $o1 punti salute in $d.  Non può essere usato in combattimento." },
    [17962] = { en = "Ignites a target that is already afflicted by your Immolate spell, dealing $s1 Fire damage and consuming your Immolate effect.", description = "Incendia un bersaglio già colpito dal tuo incantesimo Immolate, infliggendo $s1 danni da fuoco e consumando l'effetto di Immolate." },
    [18065] = { en = "Increases your attack speed by $s1%.", description = "Aumenta la tua velocità d'attacco del $s1%." },
    [19850] = { en = "Places a Blessing on the friendly target, restoring $s1 mana every $t1 seconds for $d.  Players may only have one Blessing on them per Paladin at any one time.", description = "Benedice il bersaglio amico, ripristinando $s1 mana ogni $t1 secondi per $d.  Ogni paladino può avere attiva su un giocatore una sola Benedizione alla volta." },
    [19970] = { en = "Roots the target in place and causes $o2 Nature damage over $d.  Damage caused may interrupt the effect.  Only useable outdoors.", description = "Immobilizza il bersaglio e gli infligge $o2 danni da natura in $d.  I danni inflitti possono interrompere l'effetto.  Utilizzabile solo all'aperto." },
    [24844] = { en = "Breathes lightning, instantly dealing $s1 Nature damage to a single target.", description = "Sputa un fulmine, infliggendo istantaneamente $s1 danni da natura a un singolo bersaglio." },
